import tkinter as tk
from tkinter import ttk, messagebox
import sys
import os
import subprocess
import base64
import io
from PIL import Image, ImageTk

# Embedded logo as base64
LOGO_BASE64=""""""

class RestartUI:
    def __init__(self, message, hostname, app_name="Kinetix Endpoint Agent", postpone_count=0):
        self.message = message
        self.hostname = hostname
        self.app_name = app_name
        self.postpone_count = int(postpone_count)
        self.max_postpones = 3
        
        self.root = tk.Tk()
        self.root.title(self.app_name)
        self.root.geometry("550x660")
        self.root.resizable(False, False)
        self.root.attributes("-topmost", True)
        
        # Modern color scheme
        self.colors = {
            #'bg': '#0a0e27',
            'bg': '#bf572e',
            'card': '#8c3103',
            'accent': '#ffffff',
            'accent_hover': '#2563eb',
            'success': '#10b981',
            'warning': '#f59e0b',
            'danger': '#ef4444',
            'text': '#ffffff',
            'text_secondary': '#ffffff',
            'border': '#374151'
        }
        
        # Center window
        self.root.update_idletasks()
        width = 580
        height = 680
        x = (self.root.winfo_screenwidth() // 2) - (width // 2)
        y = (self.root.winfo_screenheight() // 2) - (height // 2)
        self.root.geometry(f'{width}x{height}+{x}+{y}')
        
        self.root.configure(bg=self.colors['bg'])
        self.setup_ui()
        
        # Animation variables
        self.pulse_alpha = 0
        self.pulse_direction = 1
        self.animate_pulse()

    def load_logo(self):
        """Load logo from base64"""
        try:
            logo_data = base64.b64decode(LOGO_BASE64)
            img = Image.open(io.BytesIO(logo_data))
            img = img.resize((120, 90), Image.Resampling.LANCZOS)
            return ImageTk.PhotoImage(img)
        except Exception as e:
            print(f"Logo error: {e}")
            return None

    def create_gradient_frame(self, parent):
        """Create a frame with gradient-like effect using canvas"""
        canvas = tk.Canvas(parent, bg=self.colors['bg'], highlightthickness=0)
        canvas.pack(fill=tk.BOTH, expand=True)
        return canvas

    def setup_ui(self):
        # Main container with padding
        main_container = tk.Frame(self.root, bg=self.colors['bg'])
        main_container.pack(fill=tk.BOTH, expand=True, padx=30, pady=30)
        
        # Logo and header card with horizontal layout
        header_card = tk.Frame(main_container, bg=self.colors['card'], 
                              relief=tk.FLAT, bd=0)
        header_card.pack(fill=tk.X, pady=(0, 15))
        
        # Add subtle border effect
        header_border = tk.Frame(header_card, bg=self.colors['accent'], height=3)
        header_border.pack(side=tk.BOTTOM, fill=tk.X)
        
        # Content frame for horizontal layout
        content = tk.Frame(header_card, bg=self.colors['card'])
        content.pack(fill=tk.X, padx=20, pady=15)
        
        # Logo on the left
        self.logo_img = self.load_logo()
        if self.logo_img:
            logo_label = tk.Label(content, image=self.logo_img, bg=self.colors['card'])
            logo_label.pack(side=tk.LEFT, padx=(0, 15))
        
        # Title and device info on the right
        text_frame = tk.Frame(content, bg=self.colors['card'])
        text_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        
        title_label = tk.Label(text_frame, text=self.app_name,
                              font=('Segoe UI', 16, 'bold'),
                              fg=self.colors['text'], bg=self.colors['card'])
        title_label.pack(anchor=tk.W)
        
        device_label = tk.Label(text_frame, 
                               text=f"Device ID: {self.hostname}",
                               font=('Segoe UI', 9),
                               fg=self.colors['text_secondary'], 
                               bg=self.colors['card'])
        device_label.pack(anchor=tk.W, pady=(5, 0))
        
        # Restart required section - compact version
        warning_card = tk.Frame(main_container, bg=self.colors['warning'], 
                               relief=tk.FLAT, bd=0)
        warning_card.pack(fill=tk.X, pady=(0, 15))
        
        warning_content = tk.Frame(warning_card, bg=self.colors['warning'])
        warning_content.pack(fill=tk.X, padx=20, pady=12)
        
        restart_icon = tk.Label(warning_content, text="⚠", 
                               font=('Segoe UI', 30),
                               fg='#000', bg=self.colors['warning'])
        restart_icon.pack()
        
        restart_label = tk.Label(warning_content, 
                                text="RESTART REQUIRED",
                                font=('Segoe UI', 14, 'bold'),
                                fg='#000', bg=self.colors['warning'])
        restart_label.pack(pady=(5, 0))
        
        # Message card - compact
        msg_card = tk.Frame(main_container, bg=self.colors['card'], 
                           relief=tk.FLAT, bd=0)
        msg_card.pack(fill=tk.X, pady=(0, 12))
        
        msg_header = tk.Label(msg_card, text="Administrator Message",
                             font=('Segoe UI', 11, 'bold'),
                             fg=self.colors['accent'], bg=self.colors['card'])
        msg_header.pack(anchor=tk.W, padx=20, pady=(15, 8))
        
        msg_text = tk.Label(msg_card, text=self.message,
                           font=('Segoe UI', 10),
                           fg=self.colors['text'], bg=self.colors['card'],
                           wraplength=500, justify=tk.LEFT)
        msg_text.pack(anchor=tk.W, padx=20, pady=(0, 15))
        
        # Postpone section
        if self.postpone_count < self.max_postpones:
            postpone_card = tk.Frame(main_container, bg=self.colors['card'], relief=tk.FLAT)
            postpone_card.pack(fill=tk.X, pady=(0, 12))
            
            # Add border accent
            tk.Frame(postpone_card, bg=self.colors['accent'], height=2).pack(side=tk.TOP, fill=tk.X)
            
            content_frame = tk.Frame(postpone_card, bg=self.colors['card'])
            content_frame.pack(fill=tk.X, padx=20, pady=15)
            
            postpone_label = tk.Label(content_frame, 
                                     text="Postpone restart for:",
                                     font=('Segoe UI', 11, 'bold'),
                                     fg=self.colors['text'], 
                                     bg=self.colors['card'])
            postpone_label.pack(side=tk.LEFT, padx=(0, 15))
            
            self.later_var = tk.StringVar(value="30 minutes")
            
            # Configure modern dropdown style with better visibility
            style = ttk.Style()
            style.theme_use('clam')
            
            # Dropdown styling - white background for better visibility
            style.configure('Modern.TCombobox',
                          fieldbackground='white',
                          background=self.colors['accent'],
                          foreground='#000000',
                          borderwidth=1,
                          relief='flat',
                          arrowsize=15,
                          padding=8)
            
            style.map('Modern.TCombobox',
                     fieldbackground=[('readonly', 'white')],
                     foreground=[('readonly', '#000000')],
                     background=[('readonly', self.colors['accent'])])
            
            self.later_dropdown = ttk.Combobox(content_frame, 
                                              textvariable=self.later_var,
                                              width=18, 
                                              state="readonly",
                                              font=('Segoe UI', 11),
                                              style='Modern.TCombobox')
            self.later_dropdown['values'] = ("30 minutes", "1 hour", "2 hours", "4 hours")
            self.later_dropdown.pack(side=tk.LEFT)
            
            # Postpone counter
            counter_frame = tk.Frame(main_container, bg=self.colors['bg'])
            counter_frame.pack(fill=tk.X, pady=(0, 12))
            
            counter_label = tk.Label(counter_frame,
                                    text=f"Postponed {self.postpone_count}/{self.max_postpones} times",
                                    font=('Segoe UI', 10),
                                    fg=self.colors['text_secondary'],
                                    bg=self.colors['bg'])
            counter_label.pack()
        else:
            max_msg = tk.Label(main_container,
                             text="⚠ Maximum postpones reached. Please save your work and restart now.",
                             font=('Segoe UI', 10, 'bold'),
                             fg=self.colors['danger'],
                             bg=self.colors['bg'],
                             wraplength=500)
            max_msg.pack(pady=12)
        
        # Action buttons
        button_frame = tk.Frame(main_container, bg=self.colors['bg'])
        button_frame.pack(fill=tk.X, pady=(10, 0))
        
        # Modern button styling
        if self.postpone_count < self.max_postpones:
            later_btn = tk.Button(button_frame, text="Restart Later",
                                 command=self.restart_later,
                                 font=('Segoe UI', 10, 'bold'),
                                 bg=self.colors['card'],
                                 fg=self.colors['text'],
                                 activebackground=self.colors['border'],
                                 activeforeground=self.colors['text'],
                                 relief=tk.FLAT, bd=0,
                                 padx=30, pady=15,
                                 cursor='hand2')
            later_btn.pack(side=tk.LEFT, expand=True, fill=tk.X, padx=(0, 10))
            
            # Hover effects
            later_btn.bind('<Enter>', lambda e: later_btn.config(bg=self.colors['border']))
            later_btn.bind('<Leave>', lambda e: later_btn.config(bg=self.colors['card']))
        
        now_btn = tk.Button(button_frame, text="Restart Now",
                           command=self.restart_now,
                           font=('Segoe UI', 10, 'bold'),
                           bg=self.colors['card'],
                           fg='white',
                           activebackground=self.colors['border'],
                           activeforeground=self.colors['text'],
                           relief=tk.FLAT, bd=0,
                           padx=30, pady=15,
                           cursor='hand2')
        now_btn.pack(side=tk.RIGHT, expand=True, fill=tk.X)
        
        # Hover effects
        now_btn.bind('<Enter>', lambda e: now_btn.config(bg=self.colors['border']))
        now_btn.bind('<Leave>', lambda e: now_btn.config(bg=self.colors['card']))

    def animate_pulse(self):
        """Create a subtle pulsing animation"""
        self.pulse_alpha += 5 * self.pulse_direction
        if self.pulse_alpha >= 100:
            self.pulse_direction = -1
        elif self.pulse_alpha <= 0:
            self.pulse_direction = 1
        
        self.root.after(50, self.animate_pulse)

    def restart_now(self):
        if messagebox.askyesno("Confirm Restart", 
                              "Your computer will restart immediately.\n\nPlease ensure all your work is saved.\n\nDo you want to continue?",
                              icon='warning'):
            subprocess.run(["shutdown", "/r", "/t", "0"], shell=True)
            self.root.destroy()

    def restart_later(self):
        val_str = self.later_var.get()
        minutes = 30
        if "hour" in val_str:
            try:
                minutes = int(val_str.split()[0]) * 60
            except:
                minutes = 60
        else:
            try:
                minutes = int(val_str.split()[0])
            except:
                minutes = 30

        self.root.withdraw()
        self.postpone_count += 1
        
        wait_ms = minutes * 60 * 1000
        self.root.after(wait_ms, self.show_ui)

    def show_ui(self):
        self.setup_ui()
        self.root.deiconify()
        self.root.attributes("-topmost", True)

    def run(self):
        self.root.mainloop()

if __name__ == "__main__":
    msg = sys.argv[1] if len(sys.argv) > 1 else "Remote restart requested by administrator."
    host = sys.argv[2] if len(sys.argv) > 2 else "Unknown Device"
    count = sys.argv[3] if len(sys.argv) > 3 else 0
    
    try:
        count = int(count)
    except:
        count = 0
        
    app = RestartUI(msg, host, postpone_count=count)
    app.run()